@startuml

class WebPortal {
  + versionNumber : string
  + urlAddress : string
}

class Building {
  + id : string
  + name : string
  + energyClass : string
  + address : string
  + yearOfConstruction : int
}

class AdditionalEntry {
  + name : string
  + isPublic : boolean
}

class TextualEntry extends AdditionalEntry {}

class NumericalEntry extends AdditionalEntry {
  + value : float
  + unit : string
}

class Image {
  + fileName : string
}

class User {
  + userName : string
  + emailAddress : string
  + password : string
  + isActivated : boolean
}

class Administrator extends User {
  + idCardNumber : string
}

class Comment {
  + content : string
}

WebPortal "1" -- "*" Building : provides catalog of
WebPortal "1" -- "*" User : has
WebPortal "1" -- "*" Visitor : has
WebPortal "1" -- "*" Comment : hosts

Building "1" *-- "*" AdditionalEntry : has
Building "1" *-- "*" Image : has
Building "1" -- "1" Image : profile photo

User "1" -- "*" Building : owns
User "1" -- "*" Comment : writes
User "1" -- "*" Building : comments on

Visitor "0..1" -- "0..1" User : registers as

@enduml

